def is_even(n):
    return n % 2 == 0

An integer is even when the remainder after division by 2 is 0.

import re
from collections import Counter

def word_frequencies(sentence):
    words = re.split(r"[^\w]+", sentence.lower())
    return dict(Counter(word for word in words if word))

The sentence is converted to lowercase, split at any punctuation or whitespace, and the nonempty words are counted.

import re
def word_freq(s):
    words = re.findall(r'[a-z0-9]+', s.lower())
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    return freq

def mean_of_numeric_strings(strings):
    total = 0.0
    count = 0
    for s in strings:
        try:
            value = float(s)
        except (ValueError, TypeError):
            continue
        total += value
        count += 1
    if count == 0:
        raise ValueError("No valid numbers found.")
    return total / count

Invalid strings are skipped, and ValueError is raised if no valid numbers remain.

def mean_numeric(strings):
    nums = []
    for s in strings:
        try:
            nums.append(float(s))
        except ValueError:
            pass
    if not nums:
        raise ValueError('No valid numbers')
    return sum(nums) / len(nums)

```python
def mean_numeric_strings(values):
    numbers = []
    for value in values:
        try:
            numbers.append(float(value))
        except (ValueError, TypeError):
            continue
    if not numbers:
        raise ValueError("No valid numeric strings")
    return sum(numbers) / len(numbers)
