def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

Lists are flattened recursively, while non-list values are added as individual elements, preserving order. For example, flatten([1, [2, [3, 4]], 5]) returns [1, 2, 3, 4, 5].

def flatten(lst):
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

```python
def flatten(value):
    result = []

    def visit(item):
        if isinstance(item, list):
            for child in item:
                visit(child)
        else:
            result.append(item)

    visit(value)
    return result
```
This recursively visits nested lists and appends non-list values in their original left-to-right order.

def group_by_first_letter(words):
    groups = {}
    for word in words:
        if not word:
            continue
        key = word[0].lower()
        groups.setdefault(key, []).append(word)
    return groups

Empty strings are skipped, and the lowercase first letter is used as the key so uppercase and lowercase are grouped together.

def group_by_first(words):
    groups = {}
    for w in words:
        if not w:
            continue
        key = w[0].lower()
        groups.setdefault(key, []).append(w)
    return groups

```python
from collections import defaultdict

def group_by_first_letter(words):
    groups = defaultdict(list)
    for word in words:
        if word:
            groups[word[0].lower()].append(word)
    return dict(groups)
```
Empty strings are skipped, and lowercase keys make uppercase and lowercase first letters equivalent.
